mapper.select:
select
from ins_tag_info where 1=1
and type = #{type}

SELECT g4.id, g1.name as firstDimensionName, g1.type, g1.NAME_EN as firstDimensionNameEn, g1.code as firstDimensionCode, g1.id as firstId, g2.name as secondDimensionName, g2.NAME_EN as secondDimensionNameEn, g2.code as secondDimensionCode, g2.id as secondId, g3.name as thirdDimensionName, g3.NAME_EN as thirdDimensionNameEn, g3.code as thirdDimensionCode, g3.id as thirdId, g4.name, g4.NAME_EN as nameEn, g4.code as code, g4.enable as enable, g4.source, g4.seriousness, g4.description, g4.label_type as labelType, g4.create_time FROM ins_tag_info g4 LEFT JOIN ins_tag_info g3 ON g4.parent_id=g3.ID LEFT JOIN ins_tag_info g2 ON g3.parent_id=g2.ID LEFT JOIN ins_tag_info g1 ON g2.parent_id=g1.ID WHERE 1=1 AND g1.CODE IS NOT NULL
AND g4.type = #{model.type}
AND g4.enable = #{model.enable}
AND g4.seriousness = #{model.seriousness}
AND g1.code in
#{item}
AND g4.NAME LIKE CONCAT('%', #{model.name} ,'%')
AND g1.id = #{model.firstId}
AND g2.id = #{model.secondId}
AND g3.id = #{model.thirdId}
order by ${model.order}
order by create_time desc
